p='core/challengeplay.mjs'
s=open(p).read()
s=s.replace("""  return { fire, pause, isChainTick, chainTickEvents, autobombEvents, floorDownEvents };""","""  const kcol = eventsData.tables.contracts.columns;
  const kIdCol = kcol.indexOf('id');
  const kNoUpCol = kcol.indexOf('noUpgrades');
  const kModeCol = kcol.indexOf('mode');
  const contractRows = eventsData.tables.contracts.rows;

  // правило 8: завершение контракта; n — выполнено в забеге после завершения
  function contractEvents(done, levels) {
    let bought = false;
    for (const l of levels) {
      if (l - 0 > eps) { bought = true; break; }
    }
    const out = [];
    for (const row of contractRows) {
      if (row[kNoUpCol] === 1 && bought) continue;
      out.push({ id: row[kIdCol], mode: row[kModeCol], n: done });
    }
    return out;
  }

  const pcol = eventsData.tables.prestige.columns;
  const pIdCol = pcol.indexOf('id');
  const pMinCol = pcol.indexOf('minLevel');
  const pModeCol = pcol.indexOf('mode');
  const pNCol = pcol.indexOf('n');
  const prestigeRows = eventsData.tables.prestige.rows;

  // правило 9: престиж по уровню до сброса
  function prestigeEvents(level) {
    const out = [];
    for (const row of prestigeRows) {
      const min = row[pMinCol];
      if (!(level > min || Math.abs(level - min) <= eps)) continue;
      out.push({ id: row[pIdCol], mode: row[pModeCol], n: row[pNCol] });
    }
    return out;
  }

  return { fire, pause, isChainTick, chainTickEvents, autobombEvents, floorDownEvents, contractEvents, prestigeEvents };""")
open(p,'w').write(s)
p='core/contracts.mjs'
s=open(p).read()
s=s.replace("""  // правило 6
  function reward""","""  // правило 20: меню контрактов — бросок, только если контракта нет
  function openMenu(state, stats, gen) {
    const s = copy(state);
    if (s.contractActive < 0) rollInto(s, stats, gen);
    return s;
  }

  // правило 6
  function reward""")
s=s.replace("price, cap, lock, effect, buyAmount, buy };","price, cap, lock, effect, buyAmount, buy, openMenu };")
open(p,'w').write(s)
